Ltac dof_bchk AV a PRE MID :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let v := fresh "v" in let V1 := fresh "V1" in let V2 := fresh "V2" in let RD := fresh "RD" in let w := fresh "w" in
    destruct (accessible_readw_sr mc a 1 (accessible_sub _ _ _ a 1 AV ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(lia)
                ltac:(clear; Z.div_mod_to_equations; lia)) as (v & V1 & V2 & RD);
    PRE; clear RD;
    first [ rewrite (sxb_b8_small v) by (clear - V1; lia) | rewrite (zxb_b8_small v) by (clear - V1; lia) ];
    MID;
    shchk_join V1 V2; intros w; clear V1 V2
  end.

Section PURE.
  Context {HCEIL : HeapCeil}.

  Lemma lit_chunked_acc8 : forall m, ACONST m -> accessible m ALIT_CHUNKED 8.
  Proof. intros m AC. apply (ACONST_gbody_accessible m ALIT_CHUNKED 8 AC). vm_compute. reflexivity. Qed.

  Lemma rw_cells_CB_length' : forall m A n bs, rw_cells asegs m A [CB n bs] -> length bs = n.
  Proof. intros m A n bs [[Hwf _] _]. cbn in Hwf. destruct Hwf as [L _]. exact L. Qed.

  (* [comment removed for export] *)
  Lemma tokit_after_wf : forall r a b, cells_wf (tokit_cells_after r a b).
  Proof. intros [| |k l] a b; cbn; repeat split. Qed.
  Lemma tokit_after_sized : forall m A r a b,
    rw_cells asegs m A (tokit_cells_after r a b) -> rw_cells asegs m A [CB 40 (cells_bytes (tokit_cells_after r a b))].
  Proof.
    intros m A r a b C. rewrite <- (app_nil_r (tokit_cells_after r a b)) in C.
    apply (rw_cells_merge asegs m A [] (tokit_cells_after r a b) []) in C. cbn [app] in C. rewrite tokit_after_size in C. exact C.
  Qed.
  Lemma tokit_after_unsized : forall m A r a b,
    rw_cells asegs m A [CB 40 (cells_bytes (tokit_cells_after r a b))] -> rw_cells asegs m A (tokit_cells_after r a b).
  Proof.
    intros m A r a b C. eapply rw_cells_reshape; [exact C | apply tokit_after_wf | cbn [cells_bytes cbytes]; rewrite app_nil_r; reflexivity].
  Qed.
