Lemma te_slow : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp D : Z) (vbs : list byte) (P0 P1 P2 P4 N3 : Z),
  (7 - j = k)%nat -> (j < 7)%nat ->
  bytes_at asegs m1 vp vbs -> accessible m1 vp (Z.of_nat (length vbs)) -> mem_inv asegs m1 -> ACONST m1 ->
  vp <= D -> D + 7 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
  dof_cont Q 0xd21d8 rax spx gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 (wz ASHADOW_BASE) s11 F fc m1 ->
  dof_cont Q 0xd2038 rax spx gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 (wz ASHADOW_BASE) s11 F fc m1 ->
  P0 = ALIT_CHUNKED + Z.of_nat j -> P1 = D + Z.of_nat j -> P2 = ALIT_CHUNKED + Z.of_nat j -> P4 = D + Z.of_nat j ->
  N3 = 7 - Z.of_nat j ->
  evt asegs Q (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 (wz P0) (wz P1) (wz P2) (wz N3) (wz P4) a5 a6 a7
                       s2 s3 s4 s5 s6 s7 s8 s9 (wz ASHADOW_BASE) s11 t3 t4 t5 t6)
                  F (Z_to_bv 64 0xd1fb8) fc None m1 (seg_rom asegs)).
