Definition te_lctx (LF : list fframe) (m m1 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
    (rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
    (P E vp : Z) (vbs : list byte) (c1 : pcore) (pad7 pad2 : list byte) (g : bool) (lo shi ff fp : Z) (h0 h1 h2 h3 : word)
    (j0 j64 : list byte) (w56 : word) (e2 cpy j112 j176 ja jb jd jc : list byte) (itc : list cell) : Prop :=
  dof_ctx H LF m m1 sp spa gsz gj rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P E vp vbs c1 pad7 pad2 [CB 24 (poison_bytes 24 0)] g lo shi ff fp h0 h1 h2 h3 DOF_SH0
  /\ rw_cells asegs m1 spa (te_s1a j0 P ff w56 j64)
  /\ rw_cells asegs m1 (spa + 72) (TokItCells 0 0 (vp + Z.of_nat (length vbs)) (vp + Z.of_nat (length vbs)) (vp + Z.of_nat (length vbs)))
  /\ rw_cells asegs m1 (spa + 112) [CB 8 j112] /\ rw_cells asegs m1 (spa + 120) [CB 40 e2]
  /\ rw_cells asegs m1 (spa + 160) [CB 16 cpy] /\ rw_cells asegs m1 (spa + 176) [CB 8 j176]
  /\ rw_cells asegs m1 (ff + 32) [CB 64 ja] /\ rw_cells asegs m1 (ff + 96) itc /\ rw_cells asegs m1 (ff + 136) [CB 40 jb]
  /\ rw_cells asegs m1 (ff + 176) [CB 40 jd] /\ rw_cells asegs m1 (ff + 216) [CB 32 jc].

Ltac te_rebuild_lctx H m sp :=
  te_rebuild_ctx H m sp;
  lazymatch goal with
  | CTX : dof_ctx _ ?LF m ?mx sp ?spa ?gsz ?gj ?rav ?s0v ?s1v ?s2v ?s3v ?s4v ?s5v ?s6v ?s7v ?s8v ?s9v ?s10v ?s11v ?P ?E ?vp ?vbs ?c1 ?pad7 ?pad2 _ ?g ?lo ?shi ?ff ?fp ?h0 ?h1 ?h2 ?h3 _,
    S1A : rw_cells _ ?mx ?spa [CB 32 ?j0; _; _; _; C8 ?w56; CB 8 ?j64], ENDIT : rw_cells _ ?mx (?spa + 72) [_; _; _; _; _],
    J112 : rw_cells _ ?mx (?spa + 112) [CB 8 ?j112], END2 : rw_cells _ ?mx (?spa + 120) [CB 40 ?e2],
    CPY : rw_cells _ ?mx (?spa + 160) [CB 16 ?cpy], J176 : rw_cells _ ?mx (?spa + 176) [CB 8 ?j176],
    FIA : rw_cells _ ?mx (?ff + 32) [CB 64 ?ja], ITC : rw_cells _ ?mx (?ff + 96) ?itc, FIB : rw_cells _ ?mx (?ff + 136) [CB 40 ?jb],
    ITD : rw_cells _ ?mx (?ff + 176) [CB 40 ?jd], FIC : rw_cells _ ?mx (?ff + 216) [CB 32 ?jc] |- _ =>
    let L := fresh "LCTX" in
    assert (L : te_lctx LF m mx sp spa gsz gj rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P E vp vbs c1 pad7 pad2 g lo shi ff fp h0 h1 h2 h3
                    j0 j64 w56 e2 cpy j112 j176 ja jb jd jc itc)
      by (unfold te_lctx, te_s1a, TokItCells, wz; repeat match goal with |- _ /\ _ => split end;
          first [exact CTX| exact S1A| exact ENDIT| exact J112| exact END2| exact CPY| exact J176| exact FIA| exact ITC| exact FIB| exact ITD| exact FIC]);
    clear CTX
  end.
Scheme kc__4 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.As.X8_P_tok_stmt.tokres Sort Prop.

Lemma te_loop : forall (mu i : nat) (r : tokres) (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a3 a4 a5 a6 a7 s6x t3 t4 t5 t6 w56 : word)
    (LF : list fframe) (m m1 : mem) (spa : Z) (gsz : nat) (gj j0 j64 e2 cpy j112 j176 ja jb jd jc : list byte)
    (P E vp fld lo shi ff fp : Z) (vbs : list byte) (c c1 : pcore) (pad7 pad2 : list byte) (g : bool) (h0 h1 h2 h3 : word),
  (length vbs - i < mu)%nat -> (i <= length vbs)%nat ->
  (forall k l, r = TK_tok k l -> (i + k + l <= length vbs)%nat /\ (1 <= l)%nat) ->
  te_lctx LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P E vp vbs c1 pad7 pad2 g lo shi ff fp h0 h1 h2 h3
          j0 j64 w56 e2 cpy j112 j176 ja jb jd jc (tokit_cells_after r (vp + Z.of_nat i) (vp + Z.of_nat (length vbs))) ->
  dof_bpure sp spa gsz P E lo shi c fld vp vbs -> dof_core c c1 ->
  evt asegs (dof_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P E lo shi c pad7 pad2 vp vbs m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 (wz 7) a3 a4 a5 a6 a7
             (wz ff) (wz ALIT_CHUNKED) (wz P) (wz (P + 76)) s6x (wz (vp + Z.of_nat (length vbs)))
             (wz (Z.shiftr ff 3 + 2147450880)) (wz (ff + 96)) (wz ASHADOW_BASE) (wz ff) t3 t4 t5 t6)
